-- No pgcrypto/uuid-ossp extension dependency on purpose -- ids are generated
-- in Go (google/uuid) and passed in, not generated by Postgres, so this
-- schema needs no superuser-only CREATE EXTENSION step on a managed host.

CREATE TABLE IF NOT EXISTS parents (
    id UUID PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS devices (
    id UUID PRIMARY KEY,
    parent_id UUID NOT NULL REFERENCES parents(id) ON DELETE CASCADE,
    label TEXT NOT NULL DEFAULT '',
    model TEXT NOT NULL DEFAULT '',
    manufacturer TEXT NOT NULL DEFAULT '',
    android_version TEXT NOT NULL DEFAULT '',
    agent_version TEXT NOT NULL DEFAULT '',
    last_seen TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_devices_parent ON devices(parent_id);

-- Token stored hashed (architecture.md §6 treats device identity as
-- sensitive) -- the server never keeps the plaintext bearer token at rest,
-- only what's needed to verify one presented at request time.
CREATE TABLE IF NOT EXISTS device_tokens (
    device_id UUID PRIMARY KEY REFERENCES devices(id) ON DELETE CASCADE,
    token_hash TEXT NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- One row per device -- a policy update is a cache replacement
-- (architecture.md §2.1), not a history; version increments on every Set.
CREATE TABLE IF NOT EXISTS policies (
    device_id UUID PRIMARY KEY REFERENCES devices(id) ON DELETE CASCADE,
    version INT NOT NULL,
    policy_json JSONB NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS commands (
    id UUID PRIMARY KEY,
    device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    type TEXT NOT NULL,
    params_json JSONB,
    status TEXT NOT NULL DEFAULT 'pending',
    detail TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_commands_device_status ON commands(device_id, status);

-- id is device-generated (architecture.md §3.2), NOT server-assigned --
-- that's what makes re-syncing a backlog after a dropped connection safe.
-- TEXT, not UUID: api-spec/openapi.yaml types it as a string
-- (format: uuid is a hint, not a hard constraint); a strict UUID column
-- turns a malformed id from some future agent bug into an opaque 500
-- instead of a clean 400 -- found exactly that testing this schema.
CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    payload_json JSONB,
    received_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_events_device_kind_time ON events(device_id, kind, occurred_at DESC);
